Object.assign(siteCopyUpdates.es, {"hero_ai_lead":"Planifica resistencia y fuerza según tus objetivos. Consulta tu recuperación, prepara la nutrición y pregunta a tu entrenador de IA.","t024":"Edita ejercicios y configura series, repeticiones, carga, descanso e intensidad. Consulta el volumen y el 1RM estimado en ejercicios compatibles.","t026":"Registra repeticiones y carga, completa cada serie y usa el temporizador de descanso con vibración.","beta_goals_body":"Planifica la fuerza según tus objetivos de carrera. Consulta el volumen, el 1RM estimado y sugerencias de carga tras dos sesiones válidas.","t062":"Los entrenamientos de resistencia compatibles se cargan automáticamente mientras la cuenta COROS está conectada. Las actividades se importan a Fjelia. Para fuerza, comparte una lista de ejercicios e introduce la sesión en COROS."});
Object.assign(siteCopyUpdates.fr, {"hero_ai_lead":"Planifiez endurance et renforcement selon vos objectifs. Suivez votre récupération, préparez votre ravitaillement et échangez avec le coach IA.","t024":"Modifiez les exercices et réglez séries, répétitions, charge, repos et effort. Consultez le volume et le 1RM estimé pour les exercices compatibles.","t026":"Saisissez répétitions et charge, validez chaque série et utilisez le minuteur de repos avec vibration.","beta_goals_body":"Planifiez le renforcement selon vos objectifs de course. Consultez le volume, le 1RM estimé et les suggestions de charge après deux séances admissibles.","t062":"Les séances d’endurance compatibles sont envoyées automatiquement tant que votre compte COROS est connecté. Les activités sont importées dans Fjelia. Pour la force, partagez une liste d’exercices à saisir dans COROS."});
Object.assign(siteCopyUpdates.it, {"hero_ai_lead":"Pianifica resistenza e forza in base ai tuoi obiettivi. Segui il recupero, prepara la nutrizione e chiedi al coach IA.","t024":"Modifica gli esercizi e imposta serie, ripetizioni, carico, recupero e intensità. Consulta volume e 1RM stimato per gli esercizi idonei.","t026":"Registra ripetizioni e carico, completa ogni serie e usa il timer di recupero con vibrazione.","beta_goals_body":"Pianifica la forza in base agli obiettivi di gara. Consulta volume, 1RM stimato e suggerimenti di carico dopo due sessioni idonee.","t062":"Gli allenamenti di resistenza supportati vengono caricati automaticamente quando l’account COROS è connesso. Le attività vengono importate in Fjelia. Per la forza, condividi una lista di esercizi da inserire in COROS."});
Object.keys(siteCopyUpdates).forEach(function (lang) { Object.assign(copy[lang], siteCopyUpdates[lang]); });
